  if (!/<link[^>]*rel=["']stylesheet["'][^>]*href=["']styles\/style\.css["']/i.test(indexHtml) &&
      !/<link[^>]*href=["']styles\/style\.css["'][^>]*rel=["']stylesheet["']/i.test(indexHtml)) {
    throw new Error('index.html is missing <link rel="stylesheet" href="styles/style.css">.');
