  if (result.jumlahBerhasil !== 2) {
    throw new Error(`Expected jumlahBerhasil 2, got ${result?.jumlahBerhasil}`);
  }
  if (result.jumlahDilewati !== 2) {
    throw new Error(`Expected jumlahDilewati 2, got ${result?.jumlahDilewati}`);
  }
