const konversiValas = function (nominal, kurs) {
  if (typeof nominal !== "number" || typeof kurs !== "number") {
    throw new TypeError("Parameter nominal dan kurs harus berupa number");
  }
  return nominal * kurs;
};

// ==========================================
// 3. Arrow Function & Implicit Return
// ==========================================
