 *    Jika tidak cocok, kembalikan "coba lagi".
 * 3. Selalu gunakan `return`, bukan sekadar `console.log()` di dalam function.
 */

function checkLogin(username, password) {
  // TODO 1: Tambahkan guard clause tipe data
