// Minimal DOM Simulation for Node.js Testing
class MockElement {
  constructor(tagName = 'div', id = '') {
    this.tagName = tagName.toUpperCase();
    this.id = id;
    this.children = [];
    this.listeners = {};
    this._textContent = '';
    this.value = '';
    this.valueAsNumber = NaN;
    this.className = '';
    this.style = {};
    this.classList = {
      add: (cls) => { if (!this.className.includes(cls)) this.className += ` ${cls}`; },
      remove: (cls) => { this.className = this.className.replace(new RegExp(`\\b${cls}\\b`, 'g'), '').trim(); },
      contains: (cls) => this.className.includes(cls)
    };
  }

  get textContent() {
    if (this.children.length > 0) {
      return this.children.map(c => c.textContent).join(' ');
    }
    return this._textContent;
  }

  set textContent(val) {
    this.children = [];
    this._textContent = String(val);
  }

  addEventListener(event, fn) {
    if (!this.listeners[event]) this.listeners[event] = [];
    this.listeners[event].push(fn);
  }

  dispatchEvent(event) {
    const handlers = this.listeners[event.type] || [];
    for (const h of handlers) h(event);
  }

  replaceChildren(...nodes) {
    this.children = [...nodes];
    this._textContent = '';
  }

  appendChild(child) {
    this.children.push(child);
  }

  reset() {
    this.value = '';
    this.valueAsNumber = NaN;
  }

  focus() {}
}

function runTests() {
  console.log("=================================================================");
  console.log("AUTOMATED TEST HARNESS: SESSION 8 HANDS-ON LAB VERIFICATION");
  console.log(`Base Directory: ${baseDir}`);
